#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe curl-parameterise-a-suite-with-variables. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site staging plain
printf '%s\n' 'ok' > site/health.txt
cat > site/report.csv <<'EOF'
id,total
1,42
EOF
printf '%s\n' 'ok' > staging/health.txt
printf '%s\n' 'id,total' > staging/report.csv
printf '%s\n' 'ok' > plain/health.txt
cat > suite.conf <<'EOF'
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The suite: one config for any server. The host, port and token come from the environment;
# the host defaults to 127.0.0.1 when SURL_HOST is not set.
variable = %SURL_HOST=127.0.0.1
variable = %SURL_PORT
variable = %API_TOKEN

silent
show-error
fail
write-out = "%{url.path} %{http_code}\n"
expand-oauth2-bearer = "{{API_TOKEN:trim}}"

expand-url = "http://{{SURL_HOST}}:{{SURL_PORT:trim}}/health.txt"
out-null
expand-url = "http://{{SURL_HOST}}:{{SURL_PORT:trim}}/report.csv"
out-null
EOF
surl --directory site --user :t0ken-123 --allow-plaintext-auth http://127.0.0.1:8080/ &
sleep 1
env SURL_PORT=8080 API_TOKEN=t0ken-123 curl -K suite.conf
kill $(jobs -p)
